    public function minName(): ?string { $this->terminalArity(func_num_args()); $v = $this->runScalar($this->terminalDb(), 'min', 'name'); return $v === null ? null : (string) $v; }
    /** MAX(name); null when no rows match. */
    public function maxName(): ?string { $this->terminalArity(func_num_args()); $v = $this->runScalar($this->terminalDb(), 'max', 'name'); return $v === null ? null : (string) $v; }

    // ---- raw root (trusted code only): {table} = this entity's table, ? bound from $binds in order ----
    public function raw(string $sql, array $binds = []): static { $this->setRaw($sql, $binds); return $this; }
    /** Runs the raw() statement; rows keyed by the driver's column names, values as PDO gives them (no codec). @return list<array<string, mixed>> */
    public function rawAll(): array { $this->terminalArity(func_num_args()); return $this->runRaw($this->terminalDb()); }

    public function paginate(int $page, int $per): Page
    {
        $this->terminalArity(func_num_args(), 2);
        $db = $this->terminalDb();
        if ($per <= 0) { throw new \Orm\OrmException(\Orm\Code::IR_INVALID, 'per must be positive'); }
        [$rows, $total] = $this->runPaginate($db, $page, $per);
        return new Page(Collection::fromRows($rows, ProjectRow::class, $this->keyFn), $total, intdiv($total + $per - 1, $per), max(1, $page), $per);
    }

    public function getsAfter(string $cursor, int $per): KeysetPage
    {
        $this->terminalArity(func_num_args(), 2);
        $db = $this->terminalDb();
        $this->keyset('after', $cursor, $per, ['seq']);
        $rows = $this->runQuery($db, 'all');
        return KeysetPage::fromRows($rows, Collection::fromRows($rows, ProjectRow::class, $this->keyFn), $this->req->ir['order'] ?? []);
    }

    public function getsBefore(string $cursor, int $per): KeysetPage
    {
        $this->terminalArity(func_num_args(), 2);
        $db = $this->terminalDb();
        $this->keyset('before', $cursor, $per, ['seq']);
        $rows = $this->runQuery($db, 'all');
        $rows->reverseMain();
        return KeysetPage::fromRows($rows, Collection::fromRows($rows, ProjectRow::class, $this->keyFn), $this->req->ir['order'] ?? []);
    }

    public function insert(): ?ProjectRow
    {
        $this->terminalArity(func_num_args());
        $db = $this->terminalDb();
        $id = $this->runInsert($db);
        return Project::query()->using($db)->seqEq((int) $id)->get();
    }

    /** UPDATE when every primary-key column was assigned; otherwise INSERT. */
    public function save(): ?ProjectRow
    {
        $this->terminalArity(func_num_args());
        $db = $this->terminalDb();
        [$updated, $keys] = $this->runSave($db, ['seq']);
        if (!$updated) { $keys = [(int) $keys[0]]; }
        return Project::query()->using($db)->seqEq($keys[0])->get();
    }

    /** UPDATE the set, plus, minus and expr assignments WHERE the chain's predicates (a missing where is an engine error). @return int affected rows */
    public function update(): int { $this->terminalArity(func_num_args()); return $this->runWrite($this->terminalDb(), 'update'); }
    /** DELETE WHERE the chain's predicates (a missing where is an engine error). @return int affected rows */
    public function delete(): int { $this->terminalArity(func_num_args()); return $this->runWrite($this->terminalDb(), 'delete'); }
    /** Execute typed query drafts in one transaction with bounded chunks. */
    public function batchInsert(array $rows, ?BatchOptions $options = null): BatchResult { return $this->batchWrite($rows, 'insert', $options); }
    public function batchUpsert(array $rows, ?BatchOptions $options = null): BatchResult { return $this->batchWrite($rows, 'insert', $options); }
    public function batchUpdate(array $rows, ?BatchOptions $options = null): BatchResult { return $this->batchWrite($rows, 'update', $options); }
    public function batchDelete(array $rows, ?BatchOptions $options = null): BatchResult { return $this->batchWrite($rows, 'delete', $options); }
    /** @param list<Project> $rows */
    private function batchWrite(array $rows, string $kind, ?BatchOptions $options): BatchResult
    {
        $db = $this->terminalDb(); $requests = [];
        foreach ($rows as $row) {
            if (!$row instanceof Project) throw new \Orm\OrmException(\Orm\Code::IR_INVALID, 'batch row has the wrong type');
            $plan = $row->plan($db, $kind);
            $requests[] = ['step' => $plan['steps'][0], 'params' => $row->req->params];
        }
        return $db->batchWrite($requests, $kind, $options);
    }
    /** The main statement as the all() terminal would run it, without executing; secret slots read "$SECRET". @return array{sql: string, binds: list<mixed>} */
    public function sql(): array { $this->terminalArity(func_num_args()); return $this->runSql($this->terminalDb()); }

    public function getBySeq(int $value): ?ProjectRow
    {
        $this->terminalArity(func_num_args(), 1);
        return $this->seqEq($value)->get();
    }

}
